  [1232181] = { { "I tuoi colpi critici di Sete di Sangue, ⟦Mortal Strike=Assalto Mortale⟧, ⟦Shield Slam=Colpo di Scudo⟧, ⟦Heroic Strike=Assalto Eroico⟧ e Fendente portano la durata del tuo Squartamento sul bersaglio a $D1.", "I tuoi colpi critici di Pugnalata alle Spalle, Mutilazione e Fendente di Sciabola portano la durata della tua Perforazione sul bersaglio a $D1 e quella della tua Tempesta Cremisi a $D2.", "I tuoi colpi critici di Assalto del Raptor e Morso della Mangusta portano la durata del tuo Morso del Serpente sul bersaglio a $D1.", "Non avrai mai il merito di beneficiare di questa lama.", shape = { "1/1", "2/2", "1/1", "0/0" } }, nil, 0x2936d8d5, nil, "um" },
  [1232184] = { { "Le mosse finali dannose hanno il $N1% di probabilità per punto combo di rigenerare $N2 energia.", "Se Fendente colpisce meno bersagli del suo massimo, infligge il $N1% di danni in più per ogni rimbalzo inutilizzato.", "Il bonus ai danni di Assalto Fiancheggiato è aumentato di un ulteriore $N1% per accumulo. Quando colpisci da dietro, il bersaglio subisce il $N2% di danni in più da Assalto Fiancheggiato.", "Le lame non ti accetteranno mai come loro padrone.", shape = { "2/0", "1/0", "2/0", "0/0" } }, nil, 0x3f824d68, nil, "um" },
